    #[test]
    fn fake_conformance_suite_fails_validation() {
        // A self-test proving the validator rejects a fabricated suite id:
        // the registry can never be gamed by an unknown allowlist name.
        let fake = [ApiCoverageEvidence {
            dll: "kernel32.dll",
            export: "GetTickCount64",
            arch: ArchSet::Any,
            windows_version: WindowsVersion::Any,
            level: CoverageLevel::Conformance,
            evidence_id: "casa1-conformance:this_suite_does_not_exist_anywhere",
        }];
        let unresolved = unresolved_conformance_suites(&fake);
        assert_eq!(unresolved.len(), 1, "the fabricated suite must be reported");
        assert!(unresolved[0].contains("this_suite_does_not_exist_anywhere"));
    }

    #[test]
    fn evidence_binds_to_compiled_test_manifest() {
        // Item 235 of the audit: evidence must bind to a test that is
        // ACTUALLY compiled into a test executable and can run — not merely
        // "a function with this name exists somewhere in source".
        //
        // `cargo test -- --list` prints the compiled test names; every
        // conformance suite that is a test FN (not a test file) must appear.
        let manifest_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"));
        let mut suites = Vec::new();
        for row in COVERAGE_EVIDENCE {
            if let Some(suite) = row.evidence_id.strip_prefix("casa1-conformance:")
                && !manifest_dir
                    .join("tests")
                    .join(format!("{suite}.rs"))
                    .is_file()
            {
                suites.push(suite.to_string());
            }
        }
        if suites.is_empty() {
            return;
        }
        // Run the test harness listing (lib + integration tests).  This is
        // slow (~1-2 minutes) but it is the machine-verifiable contract:
        // a suite that is not compiled into any test binary is not evidence.
        let cargo = std::env::var("CARGO").unwrap_or_else(|_| "cargo".to_string());
        let output = std::process::Command::new(&cargo)
            .arg("test")
            .arg("--")
            .arg("--list")
            .output()
            .expect("run cargo test --list");
        assert!(
            output.status.success(),
            "cargo test --list failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        let listing = String::from_utf8_lossy(&output.stdout);
        let missing: Vec<&String> = suites
            .iter()
            .filter(|suite| !listing.contains(&format!("{suite}: test")))
            .collect();
        assert!(
            missing.is_empty(),
            "conformance suites must bind to compiled test executables;              not found in `cargo test -- --list`: {missing:?}"
        );
    }

    #[test]
    fn method_evidence_rejects_uncompiled_binding_and_resolves_real_tests() {
        // The registry must never trust an evidence name that does not bind
        // to a real compiled contract.
        let rows = [
            method_evidence(
                "d3d11.dll",
                "ID3D11Device",
                "RealFunctionTest",
                "casa1-conformance:pe_runtime_d3d11_pixel_shader_thunks_translate_and_bind_dxil",
            ),
            method_evidence(
                "ole32.dll",
                "IStream",
                "RealFileTest",
                "casa1-conformance:positive_regression",
            ),
            method_evidence(
                "x.dll",
                "IFake",
                "Unknown",
                "casa1-conformance:this_method_test_does_not_exist",
            ),
        ];
        let unresolved = unresolved_method_evidence(&rows);
        assert_eq!(
            unresolved,
            vec!["casa1-conformance:this_method_test_does_not_exist".to_string()],
            "only the uncompiled binding may be unresolved"
        );
        assert_eq!(
            unresolved_method_evidence(METHOD_COVERAGE_EVIDENCE),
            Vec::<String>::new(),
            "every shipped method evidence row must bind to a compiled test"
        );

        let found = method_coverage_evidence_for("D3D11.DLL", "id3d11device", "createpixelshader")
            .expect("the D3D11 method evidence row must resolve case-insensitively");
        assert_eq!(
            found.evidence_id,
            "casa1-conformance:d3d11_device_methods_reject_invalid_input_and_pin_vtable_outputs"
        );
        assert_eq!(
            found.level,
            CoverageLevel::Conformance,
            "method proof is conformance-level evidence"
        );
        assert_eq!(
            method_coverage_evidence_for("d3d11.dll", "ID3D11Device", "NoSuchMethod"),
            None,
            "an unbound method must not resolve"
        );
    }
